CREATE TABLE "users" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "username" varchar UNIQUE NOT NULL,
  "password_hash" varchar NOT NULL
);

CREATE TABLE "lists" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer NOT NULL,
  "name" varchar NOT NULL
);

CREATE TABLE "list_entries" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "list_id" integer NOT NULL,
  "rawg_id" integer NOT NULL,
  "status" varchar NOT NULL
);

CREATE UNIQUE INDEX ON "lists" ("user_id", "name");

CREATE UNIQUE INDEX ON "list_entries" ("list_id", "rawg_id");

COMMENT ON COLUMN "list_entries"."rawg_id" IS 'external ID from RAWG API';

COMMENT ON COLUMN "list_entries"."status" IS 'want to play, playing, or finished';

ALTER TABLE "lists" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "list_entries" ADD FOREIGN KEY ("list_id") REFERENCES "lists" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;
